import React, {useState} from 'react';
import './AddRecipe.css';
import { useForm } from "react-hook-form";
import {Form, Button, Col, Row} from 'react-bootstrap';

import axios from "axios";
import AddIngredient from "../AddIngredient/AddIngredient";

function AddRecipe() {
    const [ ingredients, setIngredients ] = useState([])
    const [formData, setFormData] = useState({
        "name": '',
        "description": '',
        "imageUrl": '',
        "ingredients": [],
        "id": null
    })

    const [listId, setListId] = useState(1);

const addIngredient = () => {
    setFormData({
        ...formData,
        ingredients: [
            ...formData.ingredients,
            {
                listId: listId,
                ingredient: '',
                unit: 'PIECE',
                quantity: ''
            }
        ]
    });
    setListId(listId + 1);
};

const updateIngredient = (ingredientObj) => {
    const updatedIngredients = formData.ingredients.map((ingredient) => {
        if (ingredient.listId === ingredientObj.listId) {
            return ingredientObj;
        }
        return ingredient;
    });
    setFormData({...formData, ingredients: updatedIngredients});
};

const removeIngredient = (ingredientObj) => {
    const updatedIngredients = formData.ingredients.filter(
        (ingredient) => ingredient.listId !== ingredientObj.listId
    );
    setFormData({...formData, ingredients: updatedIngredients});
};

const renderIngredients = formData.ingredients.map((ingredient) => (
    <AddIngredient
        key={ingredient.listId}
        ingredient={ingredient}
        ingredients={ingredients}
        listId={listId - 1}
        updateIngredient={updateIngredient}
        removeIngredient={removeIngredient}
    />
));

const handleSubmitRecipe = async (e) => {
    e.preventDefault();

    const payload = {
        ...formData,
        ingredients: formData.ingredients.map(({listId, ...rest}) => rest)
    };

    try {
        await axios.post("http://localhost:8080/api/recipes", payload);

        setFormData({
            name: '',
            description: '',
            imageUrl: '',
            ingredients: [],
            id: null
        });
        setListId(1);
        setIngredients([]);

        alert("Recipe created successfully!");
    } catch (error) {
        console.error("Error creating recipe", error);
        alert("Error creating recipe. Please try again.");
    }
};

return (
    <>
        <div className="bg">
            <div className="m-3">
                <h1 className="h3 bg-dark text-bg-primary mt-2">Add Recipe</h1>
                <Form onSubmit={handleSubmitRecipe}>
                    <Form.Group className="mb-1" controlId="formBasicName">
                        <Form.Label>Recipe Name:</Form.Label>
                        <Form.Control
                            placeholder="Name"
                            value={formData.name}
                            onChange={(e) =>
                                setFormData({...formData, name: e.target.value})
                            }
                        />
                    </Form.Group>
                    <Form.Group className="mb-1" controlId="formBasicDescription">
                        <Form.Label>Description:</Form.Label>
                        <Form.Control
                            placeholder="Description"
                            value={formData.description}
                            onChange={(e) =>
                                setFormData({...formData, description: e.target.value})
                            }
                        />
                    </Form.Group>
                    <Form.Group className="mb-1 mb-5" controlId="formBasicImageUrl">
                        <Form.Label>Image URL:</Form.Label>
                        <Form.Control
                            placeholder="URL"
                            value={formData.imageUrl}
                            onChange={(e) =>
                                setFormData({...formData, imageUrl: e.target.value})
                            }
                        />
                    </Form.Group>
                    <Row>
                        <Col>Ingredient</Col>
                        <Col>Unit</Col>
                        <Col>Quanity</Col>
                        <Col xs={1}></Col>
                    </Row>
                    <hr/>
                    <Row>
                        <br/>
                    </Row>
                    {renderIngredients}
                    <Row>
                        <br/>
                        <Button
                            variant="warning"
                            onClick={addIngredient}
                            className="mt-1"
                            type="button"
                        >
                            Add Ingredient
                        </Button>
                    </Row>
                    <Button variant="primary" type="submit" className="mb-5 mt-3">
                        Submit
                    </Button>
                </Form>
            </div>
        </div>
    </>
);
}
